        try:
            shutil.move(gz_path, os.path.join(dst_folder, fname + '.gz'))
        except Exception:
            failed_files.append(fname)
    if not failed_files:
        return {'success': True, 'message': 'All files compressed and moved successfully.', 'failed_files': []}
    else:
        return {'success': False, 'message': f'Failed to process {len(failed_files)} file(s).', 'failed_files': failed_files}

